<script setup lang="ts">
import { RefreshCw, Save, Search, Check, X, ExternalLink, Wallet, Users, MousePointer2, Building2, Copy, UserRoundPlus, Link2, ShieldCheck, SlidersHorizontal, Clock, CircleHelp } from '@lucide/vue';
const props=defineProps<{kind:'REFERRAL'|'BLOGGER';section:string}>();
const route = useRoute();
const bloggerSectionPath = (section: string) => route.path.startsWith('/crm/') ? `/crm/bloggers/${section}` : `/admin-workspace/bloggers-${section}`;
const config=useRuntimeConfig(),{token,user}=useWorkspaceSession(),access=useWorkspaceAccess();
const canWrite=computed(()=>['ADMIN','SUPERVISOR'].includes(user.value?.role||'')&&access.can('partners.write'));
const canPay=computed(()=>user.value?.role==='ADMIN'&&access.can('partners.payouts'));
const title=computed(()=>({settings:props.kind==='BLOGGER'?'Настройки блогеров':'Реферальная программа',participants:props.kind==='BLOGGER'?'Заявки и партнёры':'Участники',overview:'Блогеры',registrations:'Привлечённые организации',rewards:'Начисления',payouts:'Выплаты блогерам'}[props.section]||'Партнёры'));
const data=ref<any>(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),page=ref(1);
const form=reactive<any>({}),baseline=ref('');
const edit=ref<any>(null),decision=reactive({status:'ACTIVE',rewardPercent:'',note:'',paymentReference:'',payoutVerified:false});
const invite=reactive({email:'',displayName:''}),inviteMode=ref<'existing'|'new'>('existing'),settingsForm=ref<HTMLFormElement|null>(null);
const applicationLink=computed(()=>import.meta.client?`${location.origin}/account?tab=bloggers`:'/account?tab=bloggers');
function addBlogger(){error.value='';invite.email='';invite.displayName='';inviteMode.value='existing';edit.value={type:'invite'};}
async function copyApplication(){try{await navigator.clipboard.writeText(applicationLink.value);notice.value='Ссылка на заявку скопирована';}catch{error.value='Выделите ссылку и скопируйте её вручную';}}
async function sendInvitation(){await action(()=>api('bloggers/invite',{method:'POST',body:{email:invite.email.trim(),...(invite.displayName.trim()?{displayName:invite.displayName.trim()}:{})}}),'Блогер добавлен. Приглашение доступно в его личном кабинете → Блогерам. Передайте ему ссылку на заявку.');}
const {panel:dialogPanel,keyboard:dialogKeyboard}=useCatalogDialog(computed(()=>!!edit.value),()=>{if(!busy.value)edit.value=null;});
const fields=['name','isEnabled','rewardPercent','attributionDays','holdDays','minimumOrderAmount','firstOrderOnly','minimumPayout','signupRewardAmount','signupRewardUnit','signupHoldDays','termsText','autoSettlement'];
const body=()=>Object.fromEntries(fields.map(key=>[key,['rewardPercent','attributionDays','holdDays','minimumOrderAmount','minimumPayout','signupRewardAmount','signupHoldDays'].includes(key)?Number(form[key]):form[key]]));
const dirty=computed(()=>JSON.stringify(body())!==baseline.value);
onBeforeRouteLeave(() => !busy.value && (!(data.value && props.section === 'settings' && dirty.value) || window.confirm('Есть несохранённые настройки программы. Покинуть страницу?')));
function api(path:string,options:any={}){return $fetch<any>('/partners/admin/'+path,{baseURL:config.public.apiBase,headers:{Authorization:`Bearer ${token.value}`},timeout:15000,...options});}
function message(e:any){return Array.isArray(e?.data?.message)?e.data.message.join(' · '):e?.data?.message||'Не удалось выполнить действие. Повторите запрос.';}
async function load(reset=true){if(loading.value)return;loading.value=true;error.value='';try{data.value=await api(`${props.kind}/${props.section}`,{query:{search:search.value,page:page.value}});if(reset){Object.assign(form,data.value.settings);for(const key of ['rewardPercent','minimumOrderAmount','minimumPayout','signupRewardAmount'])form[key]=Number(form[key]);baseline.value=JSON.stringify(body());}}catch(e){error.value=message(e);}finally{loading.value=false;}}
async function action(callback:()=>Promise<any>,success:string){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await callback();notice.value=success;await load();edit.value=null;}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function save(){if(settingsForm.value&&!settingsForm.value.reportValidity())return;await action(()=>api(`${props.kind}/settings`,{method:'PATCH',body:body()}),'Настройки сохранены');}
function open(row:any,type:string){edit.value={row,type};Object.assign(decision,{status:type==='payout'?(row.status==='REQUESTED'?'APPROVED':'PAID'):'ACTIVE',rewardPercent:row.rewardPercent==null?'':String(row.rewardPercent),note:'',paymentReference:'',payoutVerified:!row.payoutVerified});}
function submit(){const {row,type}=edit.value;if(type==='participant')return action(()=>api(`participants/${row.id}`,{method:'PATCH',body:{status:decision.status,rewardPercent:decision.rewardPercent===''?null:Number(decision.rewardPercent),decisionNote:decision.note}}),'Решение сохранено');if(type==='verification')return action(()=>api(`participants/${row.id}/verification`,{method:'PATCH',body:{payoutVerified:decision.payoutVerified,note:decision.note}}),'Проверка получателя сохранена');if(type==='registration')return action(()=>api(`registrations/${row.organizationId}/verify`,{method:'POST',body:{payoutVerified:true,note:decision.note}}),'Организация проверена');return action(()=>api(`payouts/${row.id}`,{method:'PATCH',body:{status:decision.status,note:decision.note,...(decision.status==='PAID'?{paymentReference:decision.paymentReference}:{})}}),'Решение по выплате сохранено');}
const statuses:Record<string,string>={INVITED:'Ждём согласия',PENDING:'Ожидает проверки',ACTIVE:'Активен',SUSPENDED:'Приостановлен',REJECTED:'Отклонено',APPROVED:'Подтверждено',REQUESTED:'Новая заявка',PAID:'Выплачено',CANCELLED:'Отменено',REVERSED:'Сторнировано',PROSPECT:'На проверке',ON_HOLD:'Приостановлена',ARCHIVED:'Архив'};
const number=(v:any)=>Number(v||0).toLocaleString('ru-RU',{maximumFractionDigits:2});
const amount=(row:any)=>number(row.amount)+(row.unit==='BONUS'?' бонусов':' ₽');
const date=(v:string)=>v?new Date(v).toLocaleDateString('ru-RU'):'—';
const sum=(unit:string,status:string)=>number(data.value?.summary?.totals?.find((v:any)=>v.unit===unit&&v.status===status)?._sum.amount);
onMounted(()=>load());
let searchTimer:ReturnType<typeof setTimeout>|undefined;
watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load(false);},300);});
onBeforeUnmount(()=>clearTimeout(searchTimer));
watch(page,()=>load(false));
</script>
<template>
 <section class="partner-workspace crm-standard" :aria-busy="loading||busy">
  <header class="partner-page-head crm-page-header" :class="{ 'partner-settings-head': section==='settings' }"><div><h1>{{title}}</h1><p v-if="section==='settings'" class="partner-page-description">{{kind==='REFERRAL'?'Бонусы за рекомендации друзьям':'Комиссия за покупки и привлечение бизнеса'}}</p></div><div class="partner-actions"><button class="partner-button crm-button crm-button--refresh" :disabled="loading||busy||(section==='settings'&&dirty)" @click="load()"><RefreshCw :size="18"/>Обновить</button><button v-if="kind==='BLOGGER'&&['participants','overview'].includes(section)&&canWrite" class="partner-button partner-primary crm-button crm-button--primary" :disabled="busy" @click="addBlogger"><UserRoundPlus :size="18"/>Добавить блогера</button><button v-if="section==='settings'&&canWrite" class="partner-button partner-primary crm-button crm-button--primary" :disabled="busy||!dirty||!data" @click="save"><Save :size="18"/>Сохранить</button><button v-if="section==='rewards'&&canWrite" class="partner-button partner-primary crm-button crm-button--primary" :disabled="busy||!data" @click="action(()=>api('settle',{method:'POST'}),'Доступные начисления обработаны')"><Check :size="18"/>Обработать начисления</button></div></header>
  <p v-if="error" class="partner-alert" role="alert">{{error}}</p><p v-if="notice" class="partner-notice" role="status">{{notice}}</p>
  <p v-if="loading&&!data" role="status">Загружаем программу…</p><button v-if="error&&!data" class="partner-button crm-button" @click="load">Повторить загрузку</button>
  <template v-if="data">
   <form v-if="section==='settings'" ref="settingsForm" class="partner-settings" @submit.prevent="save">
    <div class="partner-settings-main">
     <fieldset class="partner-panel partner-setting-card crm-surface" :disabled="!canWrite||busy">
      <header class="partner-card-heading"><span class="partner-card-icon"><SlidersHorizontal :size="20"/></span><div><h2>Программа</h2><p>Название и доступность для клиентов</p></div><span class="partner-status crm-badge" :data-status="form.isEnabled?'ACTIVE':'SUSPENDED'">{{form.isEnabled?'Открыта':'Выключена'}}</span></header>
      <div class="partner-launch-row"><span><strong>Принимать участников</strong><small>{{kind==='BLOGGER'?'Заявки проходят проверку менеджером':'Частные клиенты присоединяются самостоятельно'}}</small></span><label class="partner-toggle crm-toggle-control"><input class="crm-check" v-model="form.isEnabled" type="checkbox" aria-label="Программа открыта для участия"/><span aria-hidden="true"/></label></div>
      <label class="partner-field">Название программы<input class="crm-input" v-model="form.name" maxlength="100" required/></label>
     </fieldset>
     <fieldset class="partner-panel partner-setting-card crm-surface" :disabled="!canWrite||busy">
      <header class="partner-card-heading"><span class="partner-card-icon"><Wallet :size="20"/></span><div><h2>{{kind==='REFERRAL'?'Бонусы за покупки':'Комиссия за покупки'}}</h2><p>{{kind==='REFERRAL'?'Вознаграждение на бонусный баланс сайта':'Денежное вознаграждение за B2C-заказы'}}</p></div></header>
      <div class="partner-form-grid"><label>{{kind==='REFERRAL'?'Бонусами за покупку, %':'Комиссия за B2C-заказ, %'}}<input class="crm-input" v-model.number="form.rewardPercent" type="number" min="0" max="100" step="0.01" required/></label><label>Минимальная сумма товаров, ₽<input class="crm-input" v-model.number="form.minimumOrderAmount" type="number" min="0" max="100000000" step="0.01" required/></label><label>Ожидание после доставки, дней<input class="crm-input" v-model.number="form.holdDays" type="number" min="0" max="365" required/></label><label v-if="kind==='BLOGGER'">Минимальная выплата, ₽<input class="crm-input" v-model.number="form.minimumPayout" type="number" min="1" max="100000000" step="0.01" required/></label></div>
      <label class="partner-option crm-toggle-row"><input class="crm-check" v-model="form.firstOrderOnly" type="checkbox"/><span><strong>Только первая покупка</strong><small>Повторные заказы не приносят вознаграждение</small></span></label>
      <div class="partner-example"><CircleHelp :size="16"/><span>С покупки на 5 000 ₽ — {{number(kind==='REFERRAL'?Math.floor(5000*Number(form.rewardPercent||0)/100):5000*Number(form.rewardPercent||0)/100)}} {{kind==='REFERRAL'?'бонусов':'₽'}}<small>Без доставки, подарочных карт и суммы, оплаченной бонусами</small></span></div>
     </fieldset>
     <fieldset v-if="kind==='BLOGGER'" class="partner-panel partner-setting-card crm-surface" :disabled="!canWrite||busy">
      <header class="partner-card-heading"><span class="partner-card-icon"><Building2 :size="20"/></span><div><h2>Привлечение салонов и бизнеса</h2><p>Фиксированная сумма за новую организацию, не за её покупки</p></div></header>
      <div class="partner-form-grid"><label>Сумма за организацию<input class="crm-input" v-model.number="form.signupRewardAmount" type="number" min="0" max="100000000" :step="form.signupRewardUnit==='BONUS'?1:0.01" required/></label><label>Вид вознаграждения<select class="crm-input" v-model="form.signupRewardUnit"><option value="RUB">Деньги на партнёрский баланс</option><option value="BONUS">Бонусы на сайте</option></select></label><label>Ожидание после проверки, дней<input class="crm-input" v-model.number="form.signupHoldDays" type="number" min="0" max="365" required/></label></div>
      <p class="partner-inline-note"><ShieldCheck :size="16"/>Один раз после проверки и активации. Сумма 0 отключает начисление.</p>
     </fieldset>
     <fieldset class="partner-panel partner-setting-card crm-surface" :disabled="!canWrite||busy">
      <header class="partner-card-heading"><span class="partner-card-icon"><Clock :size="20"/></span><div><h2>Ссылки и начисления</h2><p>Как долго сохранять приглашение и подтверждать награды</p></div></header>
      <div class="partner-form-grid"><label>Срок привязки ссылки, дней<input class="crm-input" v-model.number="form.attributionDays" type="number" min="1" max="365" required/></label></div>
      <label class="partner-option crm-toggle-row"><input class="crm-check" v-model="form.autoSettlement" type="checkbox"/><span><strong>Автоматическое подтверждение</strong><small>После доставки и окончания срока ожидания</small></span></label>
     </fieldset>
     <fieldset class="partner-panel partner-setting-card crm-surface" :disabled="!canWrite||busy">
      <header class="partner-card-heading"><span class="partner-card-icon"><ShieldCheck :size="20"/></span><div><h2>Условия программы</h2><p>Участник принимает их перед подключением</p></div></header>
      <label class="partner-field">Текст, который принимает участник<textarea class="crm-input" v-model="form.termsText" maxlength="6000" rows="6" :required="form.isEnabled" placeholder="Условия участия, правила начислений и ограничения…"/></label>
      <p class="partner-inline-note">Самоприглашения и B2B-продажи исключены. Существующие начисления не пересчитываются.</p>
     </fieldset>
    </div>
    <aside class="partner-settings-aside">
     <article class="partner-panel partner-program-summary crm-surface"><span class="partner-summary-label">СВОДКА ПРОГРАММЫ</span><h2>{{form.name||'Без названия'}}</h2><span class="partner-status crm-badge" :data-status="form.isEnabled?'ACTIVE':'SUSPENDED'">{{form.isEnabled?'Открыта для участия':'Программа выключена'}}</span><dl><div><dt>{{kind==='REFERRAL'?'Бонусы за покупку':'Комиссия за покупку'}}</dt><dd>{{number(form.rewardPercent)}}%</dd></div><div><dt>Привязка ссылки</dt><dd>{{form.attributionDays}} дней</dd></div><div><dt>После доставки</dt><dd>{{form.holdDays}} дней</dd></div><div v-if="kind==='BLOGGER'"><dt>Минимальная выплата</dt><dd>{{number(form.minimumPayout)}} ₽</dd></div><div v-if="kind==='BLOGGER'"><dt>За организацию</dt><dd>{{Number(form.signupRewardAmount)?number(form.signupRewardAmount)+(form.signupRewardUnit==='BONUS'?' бонусов':' ₽'):'Выключено'}}</dd></div></dl><p class="partner-summary-note">{{kind==='REFERRAL'?'Только бонусы для покупок на сайте. Денежных выплат нет.':'Комиссия за B2C-покупки и фиксированное вознаграждение за новый бизнес — отдельно.'}}</p><p class="partner-save-state" :data-dirty="dirty">{{!canWrite?'Только просмотр':dirty?'Есть несохранённые изменения':'Все изменения сохранены'}}</p></article>
    </aside>
   </form>
   <template v-else>
    <div v-if="section==='overview'" class="partner-kpis"><article class="partner-panel crm-surface crm-surface"><Users :size="20"/><span>Партнёры</span><strong>{{data.summary.participants}}</strong><small>{{data.summary.pending}} заявок на проверке</small></article><article class="partner-panel crm-surface crm-surface"><MousePointer2 :size="20"/><span>Уникальные посетители</span><strong>{{data.summary.uniqueVisitors}}</strong><small>после согласия по ссылке</small></article><article class="partner-panel crm-surface crm-surface"><Building2 :size="20"/><span>Привлечённые организации</span><strong>{{data.summary.registrations}}</strong><small>регистрации, не B2B-продажи</small></article><article class="partner-panel crm-surface crm-surface"><Wallet :size="20"/><span>Подтверждено деньгами</span><strong>{{sum('RUB','APPROVED')}} ₽</strong><small>до вычета выплат</small></article></div>
    <div v-if="section==='overview'" class="partner-overview"><article class="partner-panel crm-surface"><h2>В работе</h2><div class="partner-totals"><span>Деньги в ожидании<strong>{{sum('RUB','PENDING')}} ₽</strong></span><span>Бонусы в ожидании<strong>{{sum('BONUS','PENDING')}}</strong></span><span>Бонусы подтверждены<strong>{{sum('BONUS','APPROVED')}}</strong></span></div></article><article class="partner-panel crm-surface"><h2>Работа с партнёрами</h2><nav class="partner-links"><NuxtLink :to="bloggerSectionPath('participants')">Заявки и партнёры<ExternalLink :size="16"/></NuxtLink><NuxtLink :to="bloggerSectionPath('registrations')">Проверить организации<ExternalLink :size="16"/></NuxtLink><NuxtLink v-if="canPay" :to="bloggerSectionPath('payouts')">Очередь выплат<ExternalLink :size="16"/></NuxtLink></nav></article></div>
    <template v-else><div v-if="kind==='BLOGGER'&&section==='participants'" class="partner-onboarding"><span><UserRoundPlus :size="18"/><b>1.</b> Добавьте клиента или передайте ссылку</span><span><Check :size="18"/><b>2.</b> Блогер принимает условия</span><span><ShieldCheck :size="18"/><b>3.</b> Одобрите заявку</span></div><article class="partner-panel partner-registry crm-surface"><div class="partner-registry-head"><label class="partner-search crm-input-group"><Search :size="18"/><input class="crm-input" v-model="search" placeholder="Имя партнёра, email или код ссылки" aria-label="Поиск партнёров"/></label><span>{{data.total}} записей</span></div>
     <div v-if="!data.rows.length" class="partner-empty"><Users :size="28"/><h2>{{search?'Ничего не найдено':'Пока нет записей'}}</h2><p>{{search?'Попробуйте другой запрос.':'Заявки и начисления появятся после запуска программы.'}}</p></div>
     <div v-else class="partner-table-wrap"><table class="partner-table"><thead><tr><th>Партнёр</th><template v-if="section==='participants'"><th>Контакты и каналы</th><th>Ссылки / заказы</th><th>Статус</th><th>Процент</th></template><template v-else-if="section==='registrations'"><th>Организация</th><th>Вознаграждение</th><th>Статус</th></template><template v-else><th>{{section==='rewards'?'Основание':'Создано'}}</th><th>Сумма</th><th>Статус</th><th>{{section==='rewards'?'Доступно после':'Документ / решение'}}</th></template><th v-if="canWrite||canPay">Действия</th></tr></thead><tbody>
      <tr v-for="row in data.rows" :key="row.id||row.organizationId"><td><strong>{{row.displayName||row.participant?.displayName}}</strong><small>{{row.code||row.participant?.code}}</small></td>
       <template v-if="section==='participants'"><td><span>{{row.user.email}}</span><a v-for="channel in row.channels" :key="channel.url" :href="channel.url" target="_blank" rel="noopener noreferrer">{{channel.label}}<ExternalLink :size="12"/></a><small v-if="row.description">{{row.description}}</small></td><td>{{row._count.clicks}} / {{row._count.attributions}}<small>{{row._count.registrations}} организаций</small></td><td><span class="partner-status crm-badge" :data-status="row.status">{{statuses[row.status]}}</span><small v-if="kind==='BLOGGER'">{{row.payoutVerified?'Получатель проверен':'Получатель не проверен'}}</small></td><td>{{number(row.rewardPercent??data.settings.rewardPercent)}}%</td></template>
       <template v-else-if="section==='registrations'"><td><strong>{{row.organization.name}}</strong><small>ИНН {{row.organization.inn||'не указан'}}</small></td><td>{{amount(row)}}</td><td><span class="partner-status crm-badge">{{row.verifiedAt?'Проверена':'Требует проверки'}}</span><small>{{statuses[row.organization.status]||row.organization.status}} · {{row.reward?statuses[row.reward.status]:'ещё не начислено'}}</small></td></template>
       <template v-else><td>{{section==='rewards'?(row.registrationId?'Регистрация: '+row.registration?.organization.name:row.order?.orderNumber):date(row.createdAt)}}<small v-if="section==='rewards'">{{row.registrationId?'Фиксированное вознаграждение':'Комиссия за B2C-заказ'}}</small></td><td><strong>{{amount(row)}}</strong></td><td><span class="partner-status crm-badge" :data-status="row.status">{{statuses[row.status]}}</span></td><td>{{section==='rewards'?date(row.readyAt):row.paymentReference||row.decisionNote||'—'}}</td></template>
       <td v-if="canWrite||canPay"><div class="partner-row-actions"><template v-if="section==='participants'"><button v-if="canWrite" class="partner-button crm-button" @click="open(row,'participant')">Изменить</button><button v-if="canPay&&kind==='BLOGGER'" class="partner-button crm-button" @click="open(row,'verification')">Получатель</button></template><button v-if="section==='registrations'&&canWrite&&!row.verifiedAt" class="partner-button crm-button" @click="open(row,'registration')">Проверить</button><button v-if="section==='payouts'&&canPay&&['REQUESTED','APPROVED'].includes(row.status)" class="partner-button crm-button" @click="open(row,'payout')">Решение</button></div></td>
      </tr></tbody></table></div><footer class="partner-pagination"><span>Страница {{data.page}} из {{data.pages}}</span><div class="partner-actions"><button class="partner-button crm-button" :disabled="page<=1||loading" @click="page--">Назад</button><button class="partner-button crm-button" :disabled="page>=data.pages||loading" @click="page++">Далее</button></div></footer></article></template>
   </template>
  </template>
  <Teleport to="body"><div v-if="edit" class="partner-dialog-backdrop" @click.self="!busy&&(edit=null)"><section ref="dialogPanel" tabindex="-1" @keydown="dialogKeyboard" class="partner-dialog admin-dialog" role="dialog" aria-modal="true" aria-labelledby="partner-dialog-title"><header><h2 id="partner-dialog-title">{{edit.type==='invite'?'Добавить блогера':edit.type==='participant'?'Решение по участнику':edit.type==='verification'?'Проверка получателя':edit.type==='registration'?'Проверка организации':'Решение по выплате'}}</h2><button class="partner-button partner-icon crm-button crm-button--icon" :disabled="busy" aria-label="Закрыть" @click="edit=null"><X :size="20"/></button></header><form v-if="edit.type==='invite'" @submit.prevent="sendInvitation"><div class="partner-invite-tabs"><button type="button" class="partner-button crm-button" :aria-pressed="inviteMode==='existing'" @click="inviteMode='existing'">Клиент уже на сайте</button><button type="button" class="partner-button crm-button" :aria-pressed="inviteMode==='new'" @click="inviteMode='new'">Новый блогер</button></div><template v-if="inviteMode==='existing'"><p class="partner-muted">Приглашение появится в личном кабинете клиента → Блогерам. Письмо автоматически не отправляется.</p><label>Email клиента<input class="crm-input" v-model="invite.email" type="email" maxlength="254" required placeholder="name@example.ru"/></label><label>Публичное имя<input class="crm-input" v-model="invite.displayName" maxlength="120" placeholder="Необязательно"/></label></template><div class="partner-invite-link"><h3>{{inviteMode==='new'?'Ссылка на заявку':'Передайте блогеру ссылку'}}</h3><p v-if="inviteMode==='new'" class="partner-muted">Блогер регистрируется на сайте, указывает свой канал и принимает условия. Заявка появится в этом разделе.</p><label>Страница для блогера<input class="crm-input" :value="applicationLink" readonly @focus="($event.target as HTMLInputElement).select()"/></label><button class="partner-button crm-button" type="button" @click="copyApplication"><Copy :size="18"/>Скопировать ссылку на заявку</button></div><p v-if="error" class="partner-alert" role="alert">{{error}}</p><p v-if="notice" class="partner-notice" role="status">{{notice}}</p><footer><button class="partner-button crm-button" type="button" :disabled="busy" @click="edit=null">Закрыть</button><button v-if="inviteMode==='existing'" class="partner-button partner-primary crm-button crm-button--primary" type="submit" :disabled="busy"><UserRoundPlus :size="18"/>Добавить блогера</button></footer></form><form v-else @submit.prevent="submit"><template v-if="edit.type==='participant'"><p v-if="edit.row.status==='INVITED'" class="partner-muted">Ждём согласия блогера в личном кабинете → Блогерам. До этого активация недоступна.</p><label>Статус<select class="crm-input" v-model="decision.status"><option value="ACTIVE" :disabled="edit.row.status==='INVITED'">Активен</option><option value="SUSPENDED">Приостановлен</option><option value="REJECTED">Отклонён</option></select></label><label>Индивидуальный процент<input class="crm-input" v-model="decision.rewardPercent" type="number" min="0" max="100" step="0.01" placeholder="Процент программы"/></label></template><label v-if="edit.type==='verification'" class="partner-switch crm-toggle-row"><input class="crm-check" v-model="decision.payoutVerified" type="checkbox"/>Получатель и необходимые документы проверены</label><template v-if="edit.type==='payout'"><label>Решение<select class="crm-input" v-model="decision.status"><option v-if="edit.row.status==='REQUESTED'" value="APPROVED">Одобрить выплату</option><option v-if="edit.row.status==='APPROVED'" value="PAID">Подтвердить фактический перевод</option><option value="REJECTED">Отклонить заявку</option></select></label><template v-if="decision.status==='PAID'"><p class="partner-alert">Это подтверждение уже выполненного перевода, не команда отправить деньги.</p><label>Уникальный номер платёжного документа<input class="crm-input" v-model="decision.paymentReference" minlength="3" maxlength="120" required/></label></template></template><p v-if="edit.type==='registration'" class="partner-muted">Подтвердите, что организация реальная, зарегистрирована впервые по ссылке партнёра и владелец проверен. Начисление станет доступно только при активном статусе организации.</p><label>Основание решения<textarea class="crm-input" v-model="decision.note" minlength="3" maxlength="500" required rows="3"/></label><p v-if="error" class="partner-alert" role="alert">{{error}}</p><footer><button class="partner-button crm-button" :disabled="busy" type="button" @click="edit=null">Отмена</button><button class="partner-button partner-primary crm-button crm-button--primary" :disabled="busy" type="submit"><Check :size="18"/>Подтвердить</button></footer></form></section></div></Teleport>
 </section>
</template>
